import { loadState, saveState, replaceState, exportState } from './storage.js';
import { dayKey, uid, recordAttempt, editAttempt, eventsOnDay, latestEventOnDay, rebuildAllCards } from './engine.js';
import { allBooks, matchesBooks, ensureDailyPlan, planStatus, todayListeningStats, createRetrySession, pickNext, finishCurrent, sessionProgress, dueForecast } from './queue.js';
import { retrievability, FSRS_VERSION } from './scheduler.js';
import { addStudyDays, calendarDate, calendarKey, studyDayLabel } from './studyday.js';
import { tokenizeEnglish, spellingMatches } from './tokenizer.js';

const root = document.getElementById('app');
const restoreInput = document.getElementById('file-restore');
const importInput = document.getElementById('file-import');
const textInput = document.getElementById('file-text');
let state;
let view = 'home';
let listen = null;
let typeRun = null;
let textReaderId = null;
let textEditId = null;
let textFormOpen = false;
let sentenceRun = null;
let statRange = 30;
let statDay = dayKey();
let statMonth = calendarDate(statDay);

const labels = {
  home: ['首页', '听词'], today: ['今日', '今日学习'], type: ['手打', '手打强化'],
  text: ['文本', '文本库'], library: ['词库', '词库'], stats: ['统计', '学习统计'],
};

function esc(v) { return String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
function toast(message) { const el = document.getElementById('toast'); el.textContent = message; el.style.display = 'block'; clearTimeout(toast.t); toast.t = setTimeout(() => { el.style.display = 'none'; }, 1500); }
function persist() { void saveState(state); }
function wordById(id) { return state.words.find((w) => w.id === id); }
function pct(a, b) { return b ? `${Math.round(a * 100 / b)}%` : '—'; }
function dateObj(key) { return calendarDate(key); }
function download(name, text, type = 'application/json') { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([text], { type })); a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1000); }

function speak(text) {
  if (!window.speechSynthesis) return toast('当前浏览器不支持朗读');
  speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(text);
  u.lang = 'en-US'; u.rate = Number(state.settings.speechRate) || 0.92;
  speechSynthesis.speak(u);
}

function startActivity(mode, label, books = []) {
  const a = { id: uid('act'), mode, label, books: [...books], date: dayKey(), start: Date.now(), lastTouch: Date.now(), activeMs: 0 };
  state.activities.push(a); persist(); return a.id;
}
function touchActivity(id) {
  const a = state.activities.find((x) => x.id === id); if (!a) return;
  const now = Date.now(); const last = a.lastTouch || a.start || now;
  a.activeMs = (a.activeMs || 0) + Math.max(0, Math.min(now - last, 90000)); a.lastTouch = now; persist();
}
function activityMinutes(mode = null, date = dayKey()) {
  const list = state.activities.filter((a) => a.date === date && (!mode || a.mode === mode));
  const ms = list.reduce((sum, a) => sum + (a.activeMs || Math.max(0, (a.end || a.start) - a.start) || 0), 0);
  return ms ? Math.max(1, Math.round(ms / 60000)) : 0;
}

function navHtml() {
  const items = [['home', '首页'], ['today', '今日'], ['type', '手打'], ['text', '文本'], ['library', '词库']];
  return `<nav class="nav">${items.map(([id, t]) => `<button data-nav="${id}" class="${view === id ? 'on' : ''}">${t}</button>`).join('')}</nav>`;
}
function shell(content) {
  const [ey, title] = labels[view] || ['', ''];
  root.innerHTML = `<main class="shell"><header class="topbar"><div><div class="eyebrow">${ey}</div><h1>${title}</h1></div><button id="backupTop" class="soft">备份</button></header>${content}</main>${navHtml()}`;
  document.querySelectorAll('[data-nav]').forEach((b) => b.onclick = () => go(b.dataset.nav));
  document.getElementById('backupTop').onclick = backup;
}
function go(next) { speechSynthesis?.cancel(); view = next; listen = null; typeRun = null; sentenceRun = null; textReaderId = null; render(); }

function bookChips(selected, scope) {
  const books = allBooks(state);
  return `<div class="chips"><button class="chip ${selected.length ? '' : 'on'}" data-book-scope="${scope}" data-book="__all__">全部词书</button>${books.map((b) => `<button class="chip ${selected.includes(b) ? 'on' : ''}" data-book-scope="${scope}" data-book="${esc(b)}">${esc(b)}</button>`).join('')}</div>`;
}
function bindBookChips(scope, rerender) {
  document.querySelectorAll(`[data-book-scope="${scope}"]`).forEach((b) => b.onclick = () => {
    const key = scope === 'type' ? 'typeBooks' : 'todayBooks'; const name = b.dataset.book;
    if (name === '__all__') state.settings[key] = [];
    else { const a = [...state.settings[key]]; const i = a.indexOf(name); i >= 0 ? a.splice(i, 1) : a.push(name); state.settings[key] = a; }
    persist(); rerender();
  });
}

function dueCount() { return state.words.filter((w) => !w.retired && (w.card?.reps || 0) && Number(w.card.due) <= Date.now()).length; }
function renderHome() {
  const today = todayListeningStats(state, []); const mins = activityMinutes(null); const texts = state.texts.length;
  shell(`<div class="stack"><section class="card hero"><h2>听词</h2><p>首页只放总览和入口。学习计划、词书范围、筛选和统计各自在自己的页面里。</p><div class="grid4" style="margin-top:16px"><div class="statbox"><b>${state.words.filter(w => !w.retired).length}</b><span>词库总词数</span></div><div class="statbox"><b>${dueCount()}</b><span>当前到期</span></div><div class="statbox"><b>${today.newCount + today.reviewCount}</b><span>今日听音词数</span></div><div class="statbox"><b>${mins}m</b><span>今日学习时间</span></div></div></section><div class="grid2"><button id="goToday" class="entry"><b>今日学习</b><span>新词、复习、待巩固一眼看清，再开始听音。</span></button><button id="goType" class="entry"><b>手打强化</b><span>从困难词里做更强的主动提取。</span></button><button id="goText" class="entry"><b>文本库</b><span>${texts} 篇已保存文本，逐句听、循环和选词入库。</span></button><button id="goStats" class="entry"><b>学习统计</b><span>首轮熟悉率、完整月历、困难词和未来复习。</span></button></div></div>`);
  document.getElementById('goToday').onclick = () => go('today'); document.getElementById('goType').onclick = () => go('type'); document.getElementById('goText').onclick = () => go('text'); document.getElementById('goStats').onclick = () => go('stats');
}

function renderToday() {
  const books = state.settings.todayBooks || [];
  const plan = ensureDailyPlan(state, { books }); persist();
  const prog = sessionProgress(state, plan, null); const td = todayListeningStats(state, books); const mins = activityMinutes('listen');
  const selectedText = books.length ? books.join('、') : '全部词书';
  const bookRows = (books.length ? books : allBooks(state)).map((b) => { const x = todayListeningStats(state, [b]); return `<div class="bookrow"><b>${esc(b)}</b><span>${x.newCount} 新</span><span>${x.reviewCount} 复习</span><span class="mobilehide good">${x.firstGood} 熟悉</span><span class="mobilehide bad">${x.firstBad} 不熟</span></div>`; }).join('');
  shell(`<div class="stack"><section class="card hero"><div class="space"><div><h2>今天先完成这一组</h2><div class="small">${esc(selectedText)} · ${studyDayLabel()}</div></div><span class="tag">FSRS</span></div><div class="plan" style="margin-top:15px"><div class="statbox"><b>${prog.newDone} / ${prog.newTotal}</b><span>新词</span><div class="progressline"><i style="width:${prog.newTotal ? prog.newDone * 100 / prog.newTotal : 0}%"></i></div></div><div class="statbox"><b>${prog.reviewDone} / ${prog.reviewTotal}</b><span>复习</span><div class="progressline"><i style="width:${prog.reviewTotal ? prog.reviewDone * 100 / prog.reviewTotal : 0}%"></i></div></div><div class="statbox"><b class="${prog.retry ? 'bad' : ''}">${prog.retry}</b><span>待巩固</span><div class="small">不增加新词/复习分母</div></div></div><div class="row" style="margin-top:16px"><button id="startListen" class="primary">${prog.remaining ? '继续今日听音' : '今日已完成'}</button><span class="small">听音 ${mins} 分钟 · 首轮熟悉 ${pct(td.firstGood, td.firstGood + td.firstBad)}</span></div><details class="details"><summary>调整今天的计划与词书</summary><div style="margin-top:12px"><div class="small">这里只改今天。降低目标时只裁掉完全没碰过的词；已经听过的词不会被删除，也不会出现 36 / 30。</div>${bookChips(books, 'today')}<div class="grid2" style="margin-top:12px"><div class="field"><label>今天新词目标</label><input id="todayNewTarget" type="number" min="0" value="${plan.newTarget}"></div><div class="field"><label>今天复习目标</label><input id="todayReviewTarget" type="number" min="0" value="${plan.reviewTarget}"></div></div></div></details><details class="details"><summary>以后每天的默认目标</summary><div class="grid2" style="margin-top:12px"><div class="field"><label>以后默认新词</label><input id="defaultNewTarget" type="number" min="0" value="${state.settings.defaultNewTarget}"></div><div class="field"><label>以后默认复习</label><input id="defaultReviewTarget" type="number" min="0" value="${state.settings.defaultReviewTarget}"></div></div><div class="small" style="margin-top:8px">修改这里不会改变今天已经生成的计划，从下一个学习日开始使用。</div></details></section><section class="card"><h2 class="section-title">今日听音数据</h2><div class="grid4" style="margin-top:13px"><div class="statbox"><b>${td.newCount}</b><span>听音新词</span></div><div class="statbox"><b>${td.reviewCount}</b><span>听音复习</span></div><div class="statbox"><b class="good">${td.firstGood}</b><span>首轮熟悉</span></div><div class="statbox"><b class="bad">${td.firstBad}</b><span>首轮不熟</span></div></div></section><section class="card"><h2 class="section-title">各词书今天的情况</h2><div class="small">只统计听音，不混入手打。</div><div style="margin-top:8px">${bookRows || '<div class="empty">还没有词书。</div>'}</div></section></div>`);
  bindBookChips('today', renderToday);
  document.getElementById('todayNewTarget').onchange = (e) => { const requested=Math.max(0,Number(e.target.value)||0); const updated=ensureDailyPlan(state,{newTarget:requested}); persist(); if(updated.newTarget!==requested)toast(`今天已经做过 ${updated.newTarget} 个新词，目标不能再降`); renderToday(); };
  document.getElementById('todayReviewTarget').onchange = (e) => { const requested=Math.max(0,Number(e.target.value)||0); const updated=ensureDailyPlan(state,{reviewTarget:requested}); persist(); if(updated.reviewTarget!==requested)toast(`今天已经做过 ${updated.reviewTarget} 个复习词，目标不能再降`); renderToday(); };
  document.getElementById('defaultNewTarget').onchange = (e) => { state.settings.defaultNewTarget=Math.max(0,Number(e.target.value)||0); persist(); toast('已修改以后每天的新词默认值'); };
  document.getElementById('defaultReviewTarget').onchange = (e) => { state.settings.defaultReviewTarget=Math.max(0,Number(e.target.value)||0); persist(); toast('已修改以后每天的复习默认值'); };
  document.getElementById('startListen').onclick = () => { if (!prog.remaining) return toast('今天这一组已经完成'); startListen(plan); };
}

function startListen(plan) {
  const session = createRetrySession(state, plan, 'listen'); const id = pickNext(session); if (!id) return toast('今天这一组已经完成');
  listen = { plan, session, currentEventId: null, result: null, answer: false, activityId: startActivity('listen', '今日听音', plan.books), historyView: null };
  renderListen(); speak(wordById(id).en);
}
function listenCurrentWord() { const id = listen?.historyView?.wordId || listen?.session.current?.wordId; return wordById(id); }
function renderListen() {
  const w = listenCurrentWord(); if (!w) { listen = null; view = 'today'; renderToday(); return; }
  const p = sessionProgress(state, listen.plan, listen.session); const reviewing = Boolean(listen.historyView); const result = reviewing ? listen.historyView.result : listen.result; const answer = reviewing || listen.answer;
  root.innerHTML = `<main class="immersive"><div class="studytop"><button id="listenBack" class="back">‹</button><div class="studyprogress">新词 ${p.newDone} / ${p.newTotal}　复习 ${p.reviewDone} / ${p.reviewTotal}${p.retry ? `　待巩固 ${p.retry}` : ''}</div>${!reviewing ? '<button id="retireWord" class="retire">退出循环</button>' : ''}</div><div class="studybody"><button id="speakWord" class="speaker">◖))</button>${answer ? `<div class="word ${result === 'good' ? 'good' : result === 'bad' ? 'bad' : ''}">${esc(w.en)}</div><div class="meaning">${esc(w.zh || '暂无中文释义')}</div>${w.pos || w.def ? `<div class="meta">${esc(w.pos)}${w.def ? ` · ${esc(w.def)}` : ''}</div>` : ''}${w.examples?.length ? `<div class="example">${esc(w.examples[w.examples.length - 1])}</div>` : ''}<div class="source-tags">${(w.sources || []).map(s => `<span class="tag">${esc(s)}</span>`).join('')}</div>` : '<div class="small">听到以后，意思能不能直接出来？</div>'}<div class="judges"><button id="judgeGood" class="goodbtn">1　熟悉</button><button id="judgeBad" class="badbtn">2　不熟悉</button></div>${answer ? `<div class="move"><button id="prevWord" class="soft" ${listen.session.history.length ? '' : 'disabled'}>上一词</button><button id="nextWord" class="primary">${reviewing ? '回到当前词' : '下一词'}</button></div>` : ''}<div class="statusline">${reviewing ? '修改历史判断后会重新计算当天队列和 FSRS 状态。' : '当天第一次判断决定跨天调度；后续重试只负责今天学会。'}</div></div></main>`;
  document.getElementById('listenBack').onclick = () => { touchActivity(listen.activityId); listen = null; view = 'today'; renderToday(); };
  document.getElementById('speakWord').onclick = () => { speak(w.en); if (!reviewing) touchActivity(listen.activityId); };
  if (!reviewing) document.getElementById('retireWord').onclick = () => { w.retired = true; persist(); finishCurrent(listen.session, 'good'); listen.currentEventId = null; listen.result = null; listen.answer = false; if (!pickNext(listen.session)) { listen = null; view = 'today'; renderToday(); } else { renderListen(); speak(listenCurrentWord().en); } };
  document.getElementById('judgeGood').onclick = () => judgeListen('good'); document.getElementById('judgeBad').onclick = () => judgeListen('bad');
  if (answer) { document.getElementById('prevWord').onclick = () => showPreviousListen(); document.getElementById('nextWord').onclick = () => reviewing ? returnFromHistory() : nextListen(); }
}
function judgeListen(result) {
  const w = listenCurrentWord(); if (listen.historyView) { editAttempt(state, listen.historyView.eventId, result); listen.historyView.result = result; persist(); renderListen(); return; }
  if (!listen.currentEventId) { const ev = recordAttempt(state, w, 'listen', result); listen.currentEventId = ev.id; listen.session.current.eventId = ev.id; }
  else editAttempt(state, listen.currentEventId, result);
  listen.result = result; listen.answer = true; touchActivity(listen.activityId); persist(); renderListen();
}
function nextListen() {
  if (!listen.result) return; finishCurrent(listen.session, listen.result); listen.currentEventId = null; listen.result = null; listen.answer = false; touchActivity(listen.activityId);
  const id = pickNext(listen.session); if (!id) { const p = sessionProgress(state, listen.plan, listen.session); root.innerHTML = `<main class="immersive"><div class="studybody"><div class="finish"><div class="small">本轮完成</div><h2>今日听音完成</h2><div class="grid3" style="margin:18px 0"><div class="statbox"><b>${p.newDone}/${p.newTotal}</b><span>新词</span></div><div class="statbox"><b>${p.reviewDone}/${p.reviewTotal}</b><span>复习</span></div><div class="statbox"><b>${p.retry}</b><span>待巩固</span></div></div><button id="finishListen" class="primary">回到今日</button></div></div></main>`; document.getElementById('finishListen').onclick = () => { listen = null; view = 'today'; renderToday(); }; return; }
  renderListen(); speak(wordById(id).en);
}
function showPreviousListen() { const h = listen.session.history[listen.session.history.length - 1]; if (!h?.eventId) return; listen.historyView = { wordId: h.wordId, eventId: h.eventId, result: state.events.find(e => e.id === h.eventId)?.result || h.result }; renderListen(); }
function returnFromHistory() { const plan = ensureDailyPlan(state); const activityId = listen.activityId; listen = { plan, session: createRetrySession(state, plan, 'listen'), currentEventId: null, result: null, answer: false, activityId, historyView: null }; const id = pickNext(listen.session); if (!id) { listen = null; view = 'today'; renderToday(); } else { renderListen(); speak(wordById(id).en); } }

function typeCandidates() { const books = state.settings.typeBooks || []; return state.words.filter(w => !w.retired && matchesBooks(w, books)); }
function eventsSince(days) { const key = addStudyDays(dayKey(), -days + 1); return state.events.filter(e => e.date >= key); }
function typePreset(kind) {
  const candidates = typeCandidates(); const allowed = new Set(candidates.map(w => w.id)); const today = dayKey();
  if (kind === 'todayListen') return [...new Set(state.events.filter(e => e.date === today && e.mode === 'listen' && e.result === 'bad' && allowed.has(e.wordId)).map(e => e.wordId))];
  if (kind === 'todayType') return [...new Set(state.events.filter(e => e.date === today && e.mode === 'type' && e.result === 'bad' && allowed.has(e.wordId)).map(e => e.wordId))];
  if (kind === 'repeat7') { const bad = eventsSince(7).filter(e => e.result === 'bad' && allowed.has(e.wordId)); return candidates.map(w => ({ id: w.id, ev: bad.filter(e => e.wordId === w.id) })).filter(x => x.ev.length >= 2 || new Set(x.ev.map(e => e.date)).size >= 2).sort((a,b) => b.ev.length-a.ev.length).map(x => x.id); }
  const scored = candidates.map(w => { const ev = state.events.filter(e => e.wordId === w.id); const coldBad = ev.filter(e => e.cold && e.result === 'bad').length; const bad = ev.filter(e => e.result === 'bad').length; const recent = eventsSince(7).filter(e => e.wordId === w.id && e.result === 'bad').length; const r = retrievability(w.card, Date.now(), state.settings.retention); return { id: w.id, score: coldBad * 5 + bad + recent * 1.5 + (w.card?.reps ? (1-r) * 2 : 0) }; }).filter(x => x.score > 0).sort((a,b) => b.score-a.score); return scored.map(x => x.id);
}
function renderType() {
  const books = state.settings.typeBooks || []; const auto = typePreset('auto'), l = typePreset('todayListen'), t = typePreset('todayType'), r = typePreset('repeat7'); const typedToday = new Set(state.events.filter(e => e.date === dayKey() && e.mode === 'type').map(e => e.wordId)).size;
  shell(`<div class="stack"><section class="card hero"><div class="space"><div><h2>手打强化</h2><p>先给你最值得练的入口；日期、次数等精确筛选放下面。</p></div><span class="tag">${books.length ? `${books.length} 本词书` : '全部词书'}</span></div><div class="grid3" style="margin-top:13px"><div class="statbox"><b>${auto.length}</b><span>建议强化</span></div><div class="statbox"><b>${typedToday}</b><span>今日已手打</span></div><div class="statbox"><b>${activityMinutes('type')}m</b><span>手打用时</span></div></div><div class="row" style="margin-top:15px"><button id="typeStartAuto" class="primary">开始建议强化${auto.length ? ` · ${Math.min(30, auto.length)}` : ''}</button></div><details class="details"><summary>词书范围与高级筛选</summary><div style="margin-top:12px">${bookChips(books, 'type')}<div class="filtergrid" style="margin-top:12px"><div class="field"><label>指定日期</label><input id="typeDate" type="date" value="${dayKey()}"></div><div class="field"><label>失败来源</label><select id="typeMode"><option value="all">听音 + 手打</option><option value="listen">只看听音</option><option value="type">只看手打</option></select></div><div class="field"><label>至少不熟次数</label><select id="typeMin"><option>1</option><option>2</option><option>3</option><option>5</option></select></div><div class="field"><label>本轮数量</label><select id="typeLimit"><option>20</option><option selected>50</option><option>100</option><option value="0">全部</option></select></div></div><div id="customTypePreview" style="margin-top:12px"></div></div></details></section><section class="card"><h2 class="section-title">快捷入口</h2><div class="quick" style="margin-top:12px"><button data-type-preset="todayListen"><span class="num">${l.length}</span><b>今日听音不熟</b><span class="small">今天听音阶段暴露出来的词</span></button><button data-type-preset="todayType"><span class="num">${t.length}</span><b>今日手打不熟</b><span class="small">今天手打后仍然卡住</span></button><button data-type-preset="repeat7"><span class="num">${r.length}</span><b>近 7 天反复不熟</b><span class="small">近期重复失败的词</span></button><button data-type-preset="auto"><span class="num">${auto.length}</span><b>全部困难词</b><span class="small">按跨天失败与可提取率排序</span></button></div></section></div>`);
  bindBookChips('type', renderType); document.getElementById('typeStartAuto').onclick = () => startType(auto.slice(0,30), '建议强化'); document.querySelectorAll('[data-type-preset]').forEach(b => b.onclick = () => startType(typePreset(b.dataset.typePreset).slice(0,50), b.textContent.trim().replace(/\d+/,'').slice(0,20)));
  const inputs = ['typeDate','typeMode','typeMin','typeLimit']; inputs.forEach(id => document.getElementById(id).onchange = renderTypeCustom); renderTypeCustom();
}
function customTypeIds() { const date = document.getElementById('typeDate')?.value || dayKey(); const mode = document.getElementById('typeMode')?.value || 'all'; const min = Number(document.getElementById('typeMin')?.value || 1); const allowed = new Set(typeCandidates().map(w=>w.id)); const groups = new Map(); for (const e of state.events) { if (e.date !== date || e.result !== 'bad' || !allowed.has(e.wordId) || (mode !== 'all' && e.mode !== mode)) continue; groups.set(e.wordId, (groups.get(e.wordId)||0)+1); } return [...groups.entries()].filter(([,n])=>n>=min).sort((a,b)=>b[1]-a[1]).map(([id])=>id); }
function renderTypeCustom() { const box = document.getElementById('customTypePreview'); if (!box) return; const ids = customTypeIds(); const limit = Number(document.getElementById('typeLimit')?.value || 50); const q = limit ? ids.slice(0,limit) : ids; box.innerHTML = `<div class="space"><div><b>${ids.length} 个词匹配</b><div class="small">${q.slice(0,8).map(id=>esc(wordById(id)?.en)).join(' · ')}</div></div><button id="startCustomType" class="soft" ${q.length?'':'disabled'}>开始这组${q.length?` · ${q.length}`:''}</button></div>`; document.getElementById('startCustomType').onclick = () => startType(q,'自定义强化'); }
function startType(ids, label) { ids = [...new Set(ids)].filter(id => wordById(id) && !wordById(id).retired); if (!ids.length) return toast('这组暂时没有待强化词'); const fakePlan = { date: dayKey(), newIds: ids, reviewIds: [] }; const session = createRetrySession(state, fakePlan, 'type', ids); const id = pickNext(session); if (!id) return toast('这些词今天已经手打熟悉了'); typeRun = { ids, label, session, answer:false, input:'', currentEventId:null, result:null, skipped:0, activityId:startActivity('type',label,state.settings.typeBooks||[]) }; renderTypeRun(); speak(wordById(id).en); }
function typeProgress() { const done = typeRun.ids.filter(id => latestEventOnDay(state,id,dayKey(),'type')?.result === 'good').length; const bad = typeRun.ids.filter(id => latestEventOnDay(state,id,dayKey(),'type')?.result === 'bad').length; return {done,total:typeRun.ids.length,bad}; }
function renderTypeRun() { const id = typeRun.session.current?.wordId; const w = wordById(id); if (!w) return finishType(); const p = typeProgress(); root.innerHTML = `<main class="immersive"><div class="studytop"><button id="typeBack" class="back">‹</button><div class="studyprogress">${p.done} / ${p.total}${p.bad ? `　待巩固 ${p.bad}` : ''} · ${esc(typeRun.label)}</div></div><div class="studybody"><button id="typeSpeak" class="speaker">◖))</button>${!typeRun.answer ? `<div class="small">听音后写出你直接想到的中文核心意思。</div><div style="width:100%;max-width:560px;margin-top:18px"><input id="typeAnswer" style="font-size:21px;text-align:center" placeholder="写中文核心意思…" autocomplete="off"><div class="grid2" style="margin-top:10px"><button id="typeSubmit" class="primary">提交</button><button id="typeReveal" class="soft">看答案</button></div></div>` : `<div class="word ${typeRun.result==='good'?'good':typeRun.result==='bad'?'bad':''}">${esc(w.en)}</div><div class="meaning">${esc(w.zh||'暂无中文释义')}</div>${w.pos||w.def?`<div class="meta">${esc(w.pos)}${w.def?` · ${esc(w.def)}`:''}</div>`:''}${w.examples?.length?`<div class="example">${esc(w.examples[w.examples.length-1])}</div>`:''}<div class="source-tags">${(w.sources||[]).map(s=>`<span class="tag">${esc(s)}</span>`).join('')}</div><div class="typed"><b>你刚才写的是</b><div>${esc(typeRun.input||'（直接看了答案）')}</div></div><div class="judges"><button id="typeGood" class="goodbtn">1　熟悉</button><button id="typeBad" class="badbtn">2　不熟悉</button></div><div class="move"><button id="typeReplay" class="soft">重听</button><button id="typeNext" class="primary" ${typeRun.result?'':'disabled'}>下一词</button></div><div class="statusline">不自动判中文同义词对错；熟悉/不熟悉仍然作用于同一个单词历史。</div>`}</div></main>`;
  document.getElementById('typeBack').onclick = () => { touchActivity(typeRun.activityId); typeRun=null; view='type'; renderType(); }; document.getElementById('typeSpeak').onclick = () => { speak(w.en); touchActivity(typeRun.activityId); };
  if (!typeRun.answer) { const input=document.getElementById('typeAnswer'); input.value=typeRun.input; input.focus(); const reveal=(skip)=>{typeRun.input=input.value.trim(); if(skip||!typeRun.input)typeRun.skipped++; typeRun.answer=true; renderTypeRun();}; document.getElementById('typeSubmit').onclick=()=> typeRun.input||input.value.trim()?reveal(false):toast('没写内容的话点「看答案」'); document.getElementById('typeReveal').onclick=()=>reveal(true); input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();reveal(!input.value.trim());}}; }
  else { document.getElementById('typeGood').onclick=()=>judgeType('good'); document.getElementById('typeBad').onclick=()=>judgeType('bad'); document.getElementById('typeReplay').onclick=()=>speak(w.en); document.getElementById('typeNext').onclick=nextType; }
}
function judgeType(result) { const w=wordById(typeRun.session.current.wordId); if(!typeRun.currentEventId){const ev=recordAttempt(state,w,'type',result); typeRun.currentEventId=ev.id; typeRun.session.current.eventId=ev.id;} else editAttempt(state,typeRun.currentEventId,result); typeRun.result=result; touchActivity(typeRun.activityId); persist(); renderTypeRun(); }
function nextType(){ if(!typeRun.result)return; finishCurrent(typeRun.session,typeRun.result); typeRun.answer=false;typeRun.input='';typeRun.currentEventId=null;typeRun.result=null;touchActivity(typeRun.activityId);if(!pickNext(typeRun.session))finishType();else{renderTypeRun();speak(wordById(typeRun.session.current.wordId).en);} }
function finishType(){const p=typeProgress();const bad=typeRun.ids.filter(id=>latestEventOnDay(state,id,dayKey(),'type')?.result==='bad');root.innerHTML=`<main class="immersive"><div class="studybody"><div class="finish"><div class="small">本轮完成</div><h2>${esc(typeRun.label)}</h2><div class="grid3" style="margin:18px 0"><div class="statbox"><b>${p.total}</b><span>本轮词数</span></div><div class="statbox"><b class="good">${p.done}</b><span>最终熟悉</span></div><div class="statbox"><b class="bad">${bad.length}</b><span>仍不熟</span></div></div><div class="small">直接看答案 ${typeRun.skipped} 次</div><div class="row" style="justify-content:center;margin-top:18px">${bad.length?`<button id="redoType" class="primary">再练不熟 · ${bad.length}</button>`:''}<button id="finishType" class="soft">返回手打</button></div></div></div></main>`;const copy=[...bad];if(document.getElementById('redoType'))document.getElementById('redoType').onclick=()=>{const label='本轮不熟再练';typeRun=null;startType(copy,label);};document.getElementById('finishType').onclick=()=>{typeRun=null;view='type';renderType();};}

function splitSentences(body){return (String(body||'').replace(/\r/g,'').match(/[^.!?。！？\n]+[.!?。！？]+|[^.!?。！？\n]+(?=\n|$)/g)||[]).map(x=>x.trim()).filter(Boolean);}
function renderText(){
  if(textReaderId)return renderTextReader();
  const cols=[...new Set(state.texts.map(t=>t.collection||'未分类'))].sort(); const editing=textEditId?state.texts.find(t=>t.id===textEditId):null;
  shell(`<div class="stack"><section class="card hero"><div class="space"><div><h2>文本库</h2><p>保存 transcript 和文章，之后直接继续听，不用重新粘贴。</p></div><button id="newText" class="primary">${textFormOpen||editing?'收起':'新建文本'}</button></div><div class="grid3" style="margin-top:13px"><div class="statbox"><b>${state.texts.length}</b><span>篇文本</span></div><div class="statbox"><b>${cols.length}</b><span>个文本库</span></div><div class="statbox"><b>${state.texts.reduce((n,t)=>n+(t.body.match(/[A-Za-z]+/g)?.length||0),0)}</b><span>英文词量</span></div></div></section><section class="card"><h2 class="section-title">句子拆词听写</h2><div class="small">粘一句英文，自动按实际词形拆开。这里是拼写听写，不改 FSRS 熟练度。</div><textarea id="sentenceDictationText" style="min-height:105px;margin-top:10px" placeholder="The farmers are working in rural areas."></textarea><div class="row" style="margin-top:10px"><label class="small"><input id="sentenceUnique" type="checkbox" style="width:auto"> 去重后听写</label><button id="startSentenceDictation" class="primary">开始拆词听写</button></div><div id="sentencePreview" class="source-tags" style="justify-content:flex-start;margin-top:10px"></div></section>${textFormOpen||editing?`<section class="card"><h2 class="section-title">${editing?'编辑文本':'新建文本'}</h2><div class="grid2" style="margin-top:12px"><div class="field"><label>标题</label><input id="textTitle" value="${esc(editing?.title||'')}" placeholder="Test 3 Part 4"></div><div class="field"><label>所属文本库</label><input id="textCollection" value="${esc(editing?.collection||'')}" placeholder="剑18"></div></div><textarea id="textBody" style="margin-top:10px" placeholder="粘贴 transcript / 文章正文…">${esc(editing?.body||'')}</textarea><div class="row" style="margin-top:10px"><button id="saveText" class="primary">保存</button><button id="importTextFile" class="soft">导入 TXT</button></div></section>`:''}<section class="card"><div class="space"><div><h2 class="section-title">我的文本</h2><div class="small">按库筛选或搜索标题/正文。</div></div></div><div class="grid2" style="margin-top:12px"><input id="textSearch" placeholder="搜索文本"><select id="textFilter"><option value="">全部文本库</option>${cols.map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div id="textList" class="list" style="margin-top:12px"></div></section></div>`);
  document.getElementById('newText').onclick=()=>{textFormOpen=!textFormOpen;if(!textFormOpen)textEditId=null;renderText();};
  if(textFormOpen||editing){document.getElementById('saveText').onclick=saveTextItem;document.getElementById('importTextFile').onclick=()=>textInput.click();}
  const sentenceBox=document.getElementById('sentenceDictationText'),unique=document.getElementById('sentenceUnique'),preview=document.getElementById('sentencePreview');
  const drawSentencePreview=()=>{const tokens=tokenizeEnglish(sentenceBox.value,{unique:unique.checked});preview.innerHTML=tokens.slice(0,30).map(x=>`<span class="tag">${esc(x)}</span>`).join('')+(tokens.length>30?`<span class="tag">… 共 ${tokens.length} 个</span>`:'');};
  sentenceBox.oninput=drawSentencePreview; unique.onchange=drawSentencePreview; document.getElementById('startSentenceDictation').onclick=()=>startSentenceDictation(sentenceBox.value,unique.checked);
  document.getElementById('textSearch').oninput=drawTextList;document.getElementById('textFilter').onchange=drawTextList;drawTextList();
}
function startSentenceDictation(text,unique){const tokens=tokenizeEnglish(text,{unique});if(!tokens.length)return toast('这句话里没有识别到英文单词');sentenceRun={tokens,index:0,input:'',result:null,revealed:false,lookups:0,correct:0};renderSentenceRun();speak(tokens[0]);}
function renderSentenceRun(){const token=sentenceRun.tokens[sentenceRun.index];if(!token)return finishSentenceRun();root.innerHTML=`<main class="immersive"><div class="studytop"><button id="sentenceBack" class="back">‹</button><div class="studyprogress">${sentenceRun.index+1} / ${sentenceRun.tokens.length} · 句子拆词听写</div></div><div class="studybody"><button id="sentenceSpeak" class="speaker">◖))</button>${!sentenceRun.revealed?`<div class="small">听单词，写出英文拼写。</div><div style="width:100%;max-width:560px;margin-top:18px"><input id="sentenceAnswer" style="font-size:21px;text-align:center" placeholder="输入英文拼写…" autocomplete="off" autocapitalize="off"><div class="grid2" style="margin-top:10px"><button id="sentenceSubmit" class="primary">提交</button><button id="sentenceReveal" class="soft">看答案</button></div></div>`:`<div class="word ${sentenceRun.result==='good'?'good':'bad'}">${esc(token)}</div><div class="typed"><b>你写的是</b><div>${esc(sentenceRun.input||'（直接看答案）')}</div></div><div class="statusline">${sentenceRun.result==='good'?'拼写正确':'已显示正确拼写'}</div><div class="move"><button id="sentenceReplay" class="soft">重听</button><button id="sentenceNext" class="primary">下一词</button></div>`}</div></main>`;document.getElementById('sentenceBack').onclick=()=>{sentenceRun=null;view='text';renderText();};document.getElementById('sentenceSpeak').onclick=()=>speak(token);if(!sentenceRun.revealed){const input=document.getElementById('sentenceAnswer');input.value=sentenceRun.input;input.focus();const reveal=(peek)=>{sentenceRun.input=input.value.trim();sentenceRun.result=!peek&&spellingMatches(sentenceRun.input,token)?'good':'bad';if(sentenceRun.result==='good')sentenceRun.correct++;else sentenceRun.lookups++;sentenceRun.revealed=true;renderSentenceRun();};document.getElementById('sentenceSubmit').onclick=()=>{if(!input.value.trim())return toast('没写的话可以点「看答案」');reveal(false);};document.getElementById('sentenceReveal').onclick=()=>reveal(true);input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();input.value.trim()?reveal(false):reveal(true);}};}else{document.getElementById('sentenceReplay').onclick=()=>speak(token);document.getElementById('sentenceNext').onclick=()=>{sentenceRun.index++;sentenceRun.input='';sentenceRun.result=null;sentenceRun.revealed=false;if(sentenceRun.index>=sentenceRun.tokens.length)finishSentenceRun();else{renderSentenceRun();speak(sentenceRun.tokens[sentenceRun.index]);}};}}
function finishSentenceRun(){const run=sentenceRun;root.innerHTML=`<main class="immersive"><div class="studybody"><div class="finish"><div class="small">本轮完成</div><h2>句子拆词听写</h2><div class="grid3" style="margin:18px 0"><div class="statbox"><b>${run.tokens.length}</b><span>单词数</span></div><div class="statbox"><b class="good">${run.correct}</b><span>一次拼对</span></div><div class="statbox"><b class="bad">${run.lookups}</b><span>错误/看答案</span></div></div><button id="finishSentence" class="primary">返回文本</button></div></div></main>`;document.getElementById('finishSentence').onclick=()=>{sentenceRun=null;view='text';renderText();};}
function drawTextList(){const box=document.getElementById('textList');if(!box)return;const q=document.getElementById('textSearch').value.trim().toLowerCase(),c=document.getElementById('textFilter').value;const list=[...state.texts].sort((a,b)=>(b.lastOpened||b.updatedAt||0)-(a.lastOpened||a.updatedAt||0)).filter(t=>(!c||t.collection===c)&&(!q||`${t.title} ${t.collection} ${t.body}`.toLowerCase().includes(q)));box.innerHTML=list.length?list.map(t=>`<article class="textitem"><div class="space"><div><h3>${esc(t.title)}</h3><div class="small"><span class="tag">${esc(t.collection||'未分类')}</span> · ${splitSentences(t.body).length} 句</div></div></div><p class="snippet">${esc(t.body.replace(/\s+/g,' '))}</p><div class="toolbar"><button class="primary" data-open-text="${t.id}">继续听${t.sentence?` · 第 ${t.sentence+1} 句`:''}</button><button class="soft" data-edit-text="${t.id}">编辑</button><button class="danger" data-delete-text="${t.id}">删除</button></div></article>`).join(''):'<div class="empty">还没有文本。</div>';document.querySelectorAll('[data-open-text]').forEach(b=>b.onclick=()=>{textReaderId=b.dataset.openText;const t=state.texts.find(x=>x.id===textReaderId);t.lastOpened=Date.now();persist();renderTextReader();});document.querySelectorAll('[data-edit-text]').forEach(b=>b.onclick=()=>{textEditId=b.dataset.editText;textFormOpen=true;renderText();});document.querySelectorAll('[data-delete-text]').forEach(b=>b.onclick=()=>{const t=state.texts.find(x=>x.id===b.dataset.deleteText);if(confirm(`删除「${t.title}」？已加入词库的单词不会删除。`)){state.texts=state.texts.filter(x=>x.id!==t.id);persist();renderText();}});}
function saveTextItem(){const title=document.getElementById('textTitle').value.trim(),collection=document.getElementById('textCollection').value.trim()||'未分类',body=document.getElementById('textBody').value.trim();if(!title||!body)return toast('标题和正文都要填');const now=Date.now();if(textEditId){const t=state.texts.find(x=>x.id===textEditId);Object.assign(t,{title,collection,body,updatedAt:now});t.sentence=Math.min(t.sentence||0,Math.max(0,splitSentences(body).length-1));}else state.texts.unshift({id:uid('text'),title,collection,body,createdAt:now,updatedAt:now,lastOpened:0,sentence:0,hidden:false,loop:false});textEditId=null;textFormOpen=false;persist();renderText();}
function renderTextReader(){const t=state.texts.find(x=>x.id===textReaderId);if(!t){textReaderId=null;return renderText();}const ss=splitSentences(t.body);if(!ss.length)ss.push(t.body);t.sentence=Math.max(0,Math.min(ss.length-1,t.sentence||0));const sentence=ss[t.sentence],source=`${t.collection||'未分类'} · ${t.title}`;root.innerHTML=`<main class="immersive"><div class="studytop"><button id="textBack" class="back">‹</button><div class="studyprogress">${esc(t.title)}<br><span class="small">${esc(t.collection||'未分类')}</span></div><button id="textEdit" class="retire">编辑</button></div><div class="reader"><div class="reader-actions"><button id="playFull" class="soft">全文朗读</button><button id="toggleText" class="soft">${t.hidden?'显示原文':'隐藏原文'}</button><button id="toggleLoop" class="soft">单句循环 ${t.loop?'开':'关'}</button></div><div class="sentence ${t.hidden?'blur':''}">${esc(sentence)}</div><div class="sentence-nav"><button id="prevSentence" class="soft" ${t.sentence===0?'disabled':''}>上一句</button><button id="playSentence" class="primary">重听本句</button><button id="nextSentence" class="soft" ${t.sentence===ss.length-1?'disabled':''}>下一句</button></div><section class="card" style="margin-top:14px"><h3 style="margin-top:0">全文</h3><div id="fullText" class="fulltext ${t.hidden?'blur':''}">${esc(t.body)}</div></section><section class="card" style="margin-top:14px"><h3 style="margin-top:0">从本文加入单词</h3><div class="small">来源会保存为「${esc(source)}」，例句默认保存当前句。</div><div class="grid2" style="margin-top:10px"><input id="textWord" placeholder="英文单词"><input id="textZh" placeholder="中文核心义，可留空"></div><div class="row" style="margin-top:10px"><button id="useSelection" class="soft">使用选中的词</button><button id="addFromText" class="primary">加入词库</button></div></section></div></main>`;document.getElementById('textBack').onclick=()=>{speechSynthesis.cancel();textReaderId=null;view='text';renderText();};document.getElementById('textEdit').onclick=()=>{speechSynthesis.cancel();textEditId=t.id;textFormOpen=true;textReaderId=null;renderText();};document.getElementById('playFull').onclick=()=>speak(t.body);document.getElementById('playSentence').onclick=()=>speakSentence(t,sentence);document.getElementById('prevSentence').onclick=()=>{t.sentence--;persist();renderTextReader();speak(ss[t.sentence]);};document.getElementById('nextSentence').onclick=()=>{t.sentence++;persist();renderTextReader();speak(ss[t.sentence]);};document.getElementById('toggleText').onclick=()=>{t.hidden=!t.hidden;persist();renderTextReader();};document.getElementById('toggleLoop').onclick=()=>{t.loop=!t.loop;persist();renderTextReader();if(t.loop)speakSentence(t,sentence);else speechSynthesis.cancel();};document.getElementById('useSelection').onclick=()=>{const x=String(window.getSelection?.().toString()||'').trim().replace(/^[^A-Za-z'’-]+|[^A-Za-z'’-]+$/g,'');if(!x||/\s/.test(x))return toast('先只选中一个英文单词');document.getElementById('textWord').value=x;};document.getElementById('addFromText').onclick=()=>addWordFromText(source,sentence);persist();}
function speakSentence(t,sentence){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(sentence);u.lang='en-US';u.rate=Number(state.settings.speechRate)||.92;u.onend=()=>{if(t.loop&&textReaderId===t.id)setTimeout(()=>speakSentence(t,sentence),180);};speechSynthesis.speak(u);}
function addWordFromText(source,sentence){const en=document.getElementById('textWord').value.trim().toLowerCase(),zh=document.getElementById('textZh').value.trim();if(!en||/\s/.test(en))return toast('请输入一个英文单词');upsertWord({en,zh,source,example:sentence});persist();document.getElementById('textWord').value='';document.getElementById('textZh').value='';toast(`已加入 ${en}`);}

function upsertWord({en,zh='',pos='',def='',source='',example=''}){en=String(en||'').trim().toLowerCase();if(!en)return null;let w=state.words.find(x=>x.en===en);if(!w){w={id:uid('w'),en,zh,pos,def,sources:[],examples:[],retired:false,card:null};state.words.push(w);}if(zh&&!w.zh)w.zh=zh;if(pos&&!w.pos)w.pos=pos;if(def&&!w.def)w.def=def;if(source&&!w.sources.includes(source))w.sources.push(source);if(example&&!w.examples.includes(example))w.examples.push(example);return w;}
function renderLibrary(){const books=allBooks(state);shell(`<div class="stack"><section class="card hero"><div class="space"><div><h2>词库</h2><p>单词只保存一份；一本词可以同时属于多个词书。</p></div><span class="tag">${state.words.length} 词</span></div><div class="toolbar" style="margin-top:14px"><button id="importWords" class="primary">导入 CSV / TXT</button><button id="backupWords" class="soft">完整备份</button><button id="restoreWords" class="soft">恢复备份</button></div><details class="details"><summary>复习与朗读设置</summary><div class="grid2" style="margin-top:12px"><div class="field"><label>FSRS 期望记忆保持率</label><input id="retention" type="number" min="0.75" max="0.97" step="0.01" value="${state.settings.retention}"></div><div class="field"><label>朗读语速</label><input id="speechRate" type="number" min="0.5" max="1.5" step="0.05" value="${state.settings.speechRate}"></div></div><div class="small" style="margin-top:8px">调度核心：${FSRS_VERSION}。修改保持率会按历史首轮记录重新计算卡片状态。</div></details></section><section class="card"><div class="grid2"><input id="wordSearch" placeholder="搜索单词或释义"><select id="wordBook"><option value="">全部词书</option>${books.map(b=>`<option>${esc(b)}</option>`).join('')}</select></div><div id="wordList" class="list" style="margin-top:12px"></div></section></div>`);document.getElementById('importWords').onclick=()=>importInput.click();document.getElementById('backupWords').onclick=backup;document.getElementById('restoreWords').onclick=()=>restoreInput.click();document.getElementById('wordSearch').oninput=drawWordList;document.getElementById('wordBook').onchange=drawWordList;document.getElementById('retention').onchange=e=>{state.settings.retention=Math.min(.97,Math.max(.75,Number(e.target.value)||.9));rebuildAllCards(state);persist();toast('已按历史记录重新计算 FSRS');renderLibrary();};document.getElementById('speechRate').onchange=e=>{state.settings.speechRate=Math.min(1.5,Math.max(.5,Number(e.target.value)||.92));persist();};drawWordList();}
function drawWordList(){const box=document.getElementById('wordList');if(!box)return;const q=document.getElementById('wordSearch').value.trim().toLowerCase(),book=document.getElementById('wordBook').value;const list=state.words.filter(w=>(!book||w.sources.includes(book))&&(!q||`${w.en} ${w.zh}`.toLowerCase().includes(q))).slice(0,200);box.innerHTML=list.length?list.map(w=>`<div class="listitem"><div class="space"><div><h3>${esc(w.en)} ${w.retired?'<span class="tag">已退出循环</span>':''}</h3><div>${esc(w.zh||'')}</div><div class="source-tags" style="justify-content:flex-start">${w.sources.map(s=>`<span class="tag">${esc(s)}</span>`).join('')}</div></div><button class="soft" data-retire="${w.id}">${w.retired?'恢复':'退出循环'}</button></div></div>`).join(''):'<div class="empty">没有匹配的词。</div>';document.querySelectorAll('[data-retire]').forEach(b=>b.onclick=()=>{const w=wordById(b.dataset.retire);w.retired=!w.retired;persist();drawWordList();});}
function parseWordFile(text,name){const lines=String(text).replace(/^\uFEFF/,'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);const source=name.replace(/\.(csv|txt|tsv)$/i,'')||'导入词库';let count=0;for(let i=0;i<lines.length;i++){const sep=lines[i].includes('\t')?'\t':',';const parts=lines[i].split(sep).map(x=>x.trim().replace(/^"|"$/g,''));if(i===0&&/^(en|english|word|单词)$/i.test(parts[0]))continue;const [en,zh,pos,def]=parts;if(!en)continue;upsertWord({en,zh,pos,def,source});count++;}persist();toast(`已导入 ${count} 行`);renderLibrary();}
function backup(){download(`listenwrite-backup-${dayKey()}.json`,exportState(state));}

function filteredEvents(){if(!statRange)return state.events;const key=addStudyDays(dayKey(),-statRange+1);return state.events.filter(e=>e.date>=key);}
function renderStats(){const E=filteredEvents(),cold=E.filter(e=>e.cold),good=cold.filter(e=>e.result==='good').length,listenCold=cold.filter(e=>e.mode==='listen'),typeCold=cold.filter(e=>e.mode==='type'),uniq=new Set(E.map(e=>e.wordId)).size,forecast=dueForecast(state,7);shell(`<div class="stack"><section><div class="toolbar"><button class="chip ${statRange===7?'on':''}" data-range="7">7天</button><button class="chip ${statRange===30?'on':''}" data-range="30">30天</button><button class="chip ${statRange===0?'on':''}" data-range="0">全部</button></div></section><section class="grid4"><div class="statbox"><b>${pct(good,cold.length)}</b><span>首轮熟悉率</span></div><div class="statbox"><b>${uniq}</b><span>区间学习词数</span></div><div class="statbox"><b>${pct(listenCold.filter(e=>e.result==='good').length,listenCold.length)}</b><span>听音首轮</span></div><div class="statbox"><b>${pct(typeCold.filter(e=>e.result==='good').length,typeCold.length)}</b><span>手打首轮</span></div></section>${calendarHtml()}${dayDetailHtml()}<section class="card"><h2 class="section-title">未来 7 天复习量</h2><div class="forecast">${forecast.map((x,i)=>{const max=Math.max(1,...forecast.map(y=>y.count));return`<div class="forecastrow"><span>${i===0?'今天':i===1?'明天':x.date.slice(5)}</span><div class="bar"><i style="width:${x.count*100/max}%"></i></div><b>${x.count}</b></div>`;}).join('')}</div></section>${hardWordsHtml(E)}</div>`);document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{statRange=Number(b.dataset.range);renderStats();});bindCalendar();bindStatsActions();}
function calendarHtml(){const activity={};state.events.forEach(e=>activity[e.date]=(activity[e.date]||0)+1);const first=new Date(Date.UTC(statMonth.getUTCFullYear(),statMonth.getUTCMonth(),1,12)),last=new Date(Date.UTC(statMonth.getUTCFullYear(),statMonth.getUTCMonth()+1,0,12)),offset=(first.getUTCDay()+6)%7,start=new Date(first);start.setUTCDate(first.getUTCDate()-offset);const tail=6-((last.getUTCDay()+6)%7),end=new Date(last);end.setUTCDate(last.getUTCDate()+tail);const cells=[];let max=1;for(let d=new Date(start);d<=end;d.setUTCDate(d.getUTCDate()+1)){const key=calendarKey(d),n=activity[key]||0;max=Math.max(max,n);cells.push({key,n,date:new Date(d),same:d.getUTCMonth()===first.getUTCMonth()});}return`<section class="card"><div class="space"><div><h2 class="section-title">学习日历</h2><div class="small">${studyDayLabel()}。可以一直往前翻，点日期看具体记录。</div></div></div><div class="calendarbar"><button id="calPrev">‹</button><div><b>${first.getUTCFullYear()} 年 ${first.getUTCMonth()+1} 月</b></div><button id="calNext">›</button></div><div class="week"><span>一</span><span>二</span><span>三</span><span>四</span><span>五</span><span>六</span><span>日</span></div><div class="calgrid">${cells.map(c=>{const future=c.key>dayKey(),op=c.n?.14+.62*c.n/max:.04;return`<button class="day ${c.key===statDay?'sel ':''}${c.same?'':'other '}${future?'future':''}" data-stat-day="${c.key}" ${future?'disabled':''} style="background:rgba(93,119,99,${op.toFixed(2)})"><span>${c.date.getUTCDate()}</span>${c.n?`<strong>${c.n}</strong>`:''}</button>`;}).join('')}</div><div style="text-align:center;margin-top:8px"><button id="calToday" class="ghost">回到本月</button></div></section>`;}
function bindCalendar(){document.getElementById('calPrev').onclick=()=>{statMonth=new Date(Date.UTC(statMonth.getUTCFullYear(),statMonth.getUTCMonth()-1,1,12));renderStats();};document.getElementById('calNext').onclick=()=>{const n=new Date(Date.UTC(statMonth.getUTCFullYear(),statMonth.getUTCMonth()+1,1,12)),cur=calendarDate(dayKey());cur.setUTCDate(1);if(n<=cur){statMonth=n;renderStats();}};document.getElementById('calToday').onclick=()=>{statDay=dayKey();statMonth=calendarDate(statDay);renderStats();};document.querySelectorAll('[data-stat-day]').forEach(b=>b.onclick=()=>{statDay=b.dataset.statDay;statMonth=calendarDate(statDay);renderStats();});}
function dayDetailHtml(){const ev=state.events.filter(e=>e.date===statDay).sort((a,b)=>a.ts-b.ts),ids=[...new Set(ev.map(e=>e.wordId))];const rows=ids.map(id=>{const w=wordById(id),a=ev.filter(e=>e.wordId===id),first=a.find(e=>e.cold)||a[0],bad=a.filter(e=>e.result==='bad').length,l=a.filter(e=>e.mode==='listen').length,t=a.filter(e=>e.mode==='type').length;return{w,a,first,bad,l,t};}).filter(x=>x.w).sort((a,b)=>b.bad-a.bad||a.w.en.localeCompare(b.w.en));const cold=ev.filter(e=>e.cold),good=cold.filter(e=>e.result==='good').length;return`<section class="card"><div class="space"><div><h2 class="section-title">${statDay} 详情</h2><div class="small">首轮熟悉 ${pct(good,cold.length)} · ${rows.length} 个词 · ${ev.length} 次判断</div></div>${rows.some(x=>x.bad)?'<button id="practiceDayBad" class="soft">手打当天不熟</button>':''}</div><div style="margin-top:10px">${rows.length?rows.map(x=>`<div class="bookrow"><b>${esc(x.w.en)}</b><span class="${x.first?.result==='good'?'good':'bad'}">首轮${x.first?.result==='good'?'熟悉':'不熟'}</span><span>不熟 ${x.bad}</span><span class="mobilehide">听 ${x.l}</span><span class="mobilehide">写 ${x.t}</span></div>`).join(''):'<div class="empty">这一天没有记录。</div>'}</div></section>`;}
function hardWordsHtml(E){const map=new Map();for(const e of E){if(!map.has(e.wordId))map.set(e.wordId,{coldBad:0,bad:0,events:[]});const g=map.get(e.wordId);g.events.push(e);if(e.result==='bad'){g.bad++;if(e.cold)g.coldBad++;}}const hard=[...map.entries()].map(([id,g])=>{const w=wordById(id);if(!w)return null;const r=retrievability(w.card,Date.now(),state.settings.retention);return{w,g,score:g.coldBad*5+g.bad+(w.card?.reps?(1-r)*2:0)};}).filter(x=>x&&x.g.bad).sort((a,b)=>b.score-a.score).slice(0,12);return`<section class="card"><div class="space"><div><h2 class="section-title">困难词</h2><div class="small">跨天首轮失败权重最高，再参考重复失败和可提取率。</div></div>${hard.length?'<button id="practiceHard" class="soft">手打这批</button>':''}</div>${hard.length?hard.map(x=>`<div class="harditem"><div class="space"><div><div class="title">${esc(x.w.en)}</div><div class="small">首轮不熟 ${x.g.coldBad} · 总不熟 ${x.g.bad} · FSRS可提取率 ${Math.round(retrievability(x.w.card,Date.now(),state.settings.retention)*100)}%</div></div><div>${esc(x.w.zh)}</div></div><div class="history">${x.g.events.slice(-8).map(e=>`<span class="pill ${e.result}">${e.date.slice(5)} ${e.mode==='type'?'写':'听'} ${e.result==='good'?'熟':'不熟'}</span>`).join('')}</div></div>`).join(''):'<div class="empty">这个区间没有不熟记录。</div>'}</section>`;}
function bindStatsActions(){const d=state.events.filter(e=>e.date===statDay&&e.result==='bad').map(e=>e.wordId);if(document.getElementById('practiceDayBad'))document.getElementById('practiceDayBad').onclick=()=>{view='type';startType([...new Set(d)],`${statDay} 不熟词`);};const E=filteredEvents(),scored=[...new Set(E.filter(e=>e.result==='bad').map(e=>e.wordId))].slice(0,30);if(document.getElementById('practiceHard'))document.getElementById('practiceHard').onclick=()=>{view='type';startType(scored,'困难词');};}

function render(){try{if(listen)return renderListen();if(typeRun)return renderTypeRun();if(sentenceRun)return renderSentenceRun();if(textReaderId)return renderTextReader();if(view==='home')renderHome();else if(view==='today')renderToday();else if(view==='type')renderType();else if(view==='text')renderText();else if(view==='library')renderLibrary();else renderStats();}catch(err){console.error(err);root.innerHTML=`<div class="app-error card"><h2>页面渲染失败</h2><p>数据没有被清空。刷新后仍有问题可以把这段发给我。</p><pre>${esc(err?.stack||err)}</pre></div>`;}}

restoreInput.onchange=async()=>{const f=restoreInput.files?.[0];if(!f)return;try{state=await replaceState(JSON.parse(await f.text()));toast('备份已恢复');view='home';render();}catch{toast('备份文件无法读取');}restoreInput.value='';};
importInput.onchange=async()=>{const f=importInput.files?.[0];if(!f)return;parseWordFile(await f.text(),f.name);importInput.value='';};
textInput.onchange=async()=>{const f=textInput.files?.[0];if(!f)return;textFormOpen=true;renderText();document.getElementById('textTitle').value=f.name.replace(/\.txt$/i,'');document.getElementById('textBody').value=await f.text();textInput.value='';};
window.addEventListener('keydown',(e)=>{if(listen){if(e.key==='1')judgeListen('good');else if(e.key==='2')judgeListen('bad');else if(e.key==='Enter'&&listen.answer)nextListen();else if((e.key==='Backspace'||e.key==='ArrowLeft')&&listen.answer){e.preventDefault();showPreviousListen();}}else if(typeRun&&typeRun.answer){if(e.key==='1')judgeType('good');else if(e.key==='2')judgeType('bad');else if(e.key==='Enter'&&typeRun.result)nextType();}});

(async function init(){state=await loadState();render();})();
